import{z as B,x as A,o as t,c as p,q as o,j as i,D as E,d as n,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"多重检验纪律的现场用法","description":"","frontmatter":{"title":"多重检验纪律的现场用法","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/multitest-discipline-cap.md","filePath":"quant/multitest-discipline-cap.md","lastUpdated":1791413859000}'),d={name:"quant/multitest-discipline-cap.md"};function h(C,a,u,D,f,m){const r=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="多重检验纪律的现场用法" tabindex="-1">多重检验纪律的现场用法 <a class="header-anchor" href="#多重检验纪律的现场用法" aria-label="Permalink to &quot;多重检验纪律的现场用法&quot;">​</a></h1><div class="epigraph"><p>在一个检验过数百个因子的世界里，t=2 不再是门槛，而是起跑线。</p><footer>—— 据 Harvey, Liu and Zhu (2016) 对多重检验后 t 统计量门槛的讨论整理</footer></div><p><a href="/quant/single-signal-eval">上一课</a>让 IC、换手与成本第一次会师：毛指标活着，净指标悬而未决。悬着的那部分正是本课要清算的。本课是「假设与数据」单元的收束：<a href="/quant/multiple-testing-factors">多重检验与 p-hacking</a> 给了理论，<a href="/quant/pbo">Probability of Backtest Overfitting</a>、<a href="/quant/cscv">CSCV 组合对称交叉验证</a>与 <a href="/quant/deflated-sharpe">Deflated Sharpe</a> 给了工具；本课不重讲任何一个，只演示它们在<strong>这一次</strong>研究中如何被选用与报告——防止纪律沦为仪式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纪律沦为仪式有三种形态。其一是装饰：跑完全部流程，报告里引用 CSCV 与 DSR 的文献，却不写 N 从哪来——修正量没有输入，引用等于没引用。其二是择优：三种修正都跑，只报告最松的那个，这本身就是又一次多重检验。其三是误用：把为「策略对基准」设计的检验套在别的对象上。缺口的本质：工具课讲的是每个工具回答什么问题，没讲一次具体研究该买哪几样、报告的读者是谁。</p><p><span class="marginnote">「修正量」指 DSR、PBO 这类工具算出来的打折门槛。可以把它们想象成计算器：输入不了「试了多少次、各次表现差多少」，就永远按不出结果。所以报告里引用了文献却不写 N，等于展示了一台从没插电的计算器——仪式做完了，折扣一分没打。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对本单元的 PEAD 案例现场走一遍。第一步，<strong>数 N</strong>：注册文档加偏离记录给出 N=23（11 个定义变体、4 个持有期、3 个中性化方案、5 次口径修正）。N 是台账产物，不是回忆产物。第二步，选工具并写明各自回答的问题：</p><ul><li><strong>Deflated Sharpe</strong>：回答「N 次试验里最好的那个 Sharpe，期望该是多少」。输入 N、各试验 Sharpe 的方差、偏度峰度、样本长度；输出缩水后的门槛，样本内 t 对照它判断。</li><li><strong>CSCV / PBO</strong>：回答「选中的变体是不是只是运气最好的那个」。对变体表现矩阵做组合对称切分，PBO 接近 0.5 就意味着样本内最优与样本外表现几乎脱钩。</li><li><strong>Romano-Wolf / SPA</strong>：回答「多空组合跑赢基准的部分在家族校正后是否仍显著」（<a href="/quant/fdr-romano-wolf">FDR / Romano-Wolf</a>、<a href="/quant/hansen-spa">Hansen SPA 检验</a>；bootstrap 原型是 <a href="/quant/white-reality-check">White Reality Check</a>）。这是主结论的最终闸门。</li></ul><p>三个工具回答三个不同问题：全部报告，不择优。第三步，<strong>报告口径</strong>：注册与偏离、N、每个工具的输入输出、缩水后是否仍站在评估课的门槛上；探索性结果单列一节并标注。（本段数字为演示口径。）</p><p><span class="marginnote">Harvey、Liu 与 Zhu 的清单里收了三百多个候选因子，并估计新异象的 t 门槛应抬到 3.0 量级。门槛不是更严了，而是终于把「这条文献里已经试过多少次」计进价里。</span></p><p>N 不是拍出来的总数，而是各类选择逐项累加的结果：</p>',12)),(t(),i(s,null,{default:E(()=>[l(r,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%AE%9A%E4%B9%89%E5%8F%98%E4%BD%93%20%C3%9711%22%5D%20--%3E%20N%5B%22%E5%8F%B0%E8%B4%A6%20N%20%3D%2023%22%5D%0A%20%20B%5B%22%E6%8C%81%E6%9C%89%E6%9C%9F%20%C3%974%22%5D%20--%3E%20N%0A%20%20C%5B%22%E4%B8%AD%E6%80%A7%E5%8C%96%E6%96%B9%E6%A1%88%20%C3%973%22%5D%20--%3E%20N%0A%20%20D%5B%22%E5%8F%A3%E5%BE%84%E4%BF%AE%E6%AD%A3%20%C3%975%22%5D%20--%3E%20N%0A%20%20N%20--%3E%20OUT%5B%22%E6%89%80%E6%9C%89%E4%BF%AE%E6%AD%A3%E5%B7%A5%E5%85%B7%E7%9A%84%E5%85%AC%E5%85%B1%E8%BE%93%E5%85%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：PBO 的取值在 0 与 1 之间，衡量「样本内选中的最优变体，样本外落入表现较差那一半」的频率。PBO = 0.5 意味着你的挑选和掷硬币一样准；若 23 个变体算出 PBO ≈ 0.48，翻译成人话就是——你挑中的那个大概率不是真的好，只是抽签抽得好。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),(t(),i(s,null,{default:E(()=>[l(r,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEDGER%5B%22%E5%8F%B0%E8%B4%A6%EF%BC%9A%E6%B3%A8%E5%86%8C%20%2B%20%E5%81%8F%E7%A6%BB%20%E2%86%92%20N%22%5D%20--%3E%20DSR%5B%22DSR%EF%BC%9A%E9%80%89%E6%8B%A9%E5%90%8E%E7%9A%84%E7%BC%A9%E6%B0%B4%E9%97%A8%E6%A7%9B%22%5D%0A%20%20LEDGER%20--%3E%20CSCV%5B%22CSCV%20%2F%20PBO%EF%BC%9A%E9%80%89%E6%8B%A9%E8%A7%84%E5%88%99%E7%9A%84%E8%B4%A8%E9%87%8F%22%5D%0A%20%20LEDGER%20--%3E%20RW%5B%22SPA%20%2F%20Romano-Wolf%EF%BC%9A%E5%AE%B6%E6%97%8F%E6%98%BE%E8%91%97%E6%80%A7%22%5D%0A%20%20DSR%20--%3E%20REP%5B%22%E7%BB%9F%E4%B8%80%E6%8A%A5%E5%91%8A%EF%BC%9A%E8%BE%93%E5%85%A5%20%2B%20%E8%BE%93%E5%87%BA%20%2B%20%E5%88%A4%E5%AE%9A%22%5D%0A%20%20CSCV%20--%3E%20REP%0A%20%20RW%20--%3E%20REP%0A%20%20REP%20--%3E%20GATE%7B%22%E7%BC%A9%E6%B0%B4%E5%90%8E%E4%BB%8D%E5%9C%A8%E8%AF%84%E4%BC%B0%E8%AF%BE%E9%97%A8%E6%A7%9B%E4%B8%8A%22%7D%0A%20%20GATE%20--%3E%7C%E8%BF%87%7C%20NEXT%5B%22%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E5%8D%95%E5%85%83%EF%BC%9A%E7%BB%84%E5%90%88%E6%95%B4%E5%90%88%22%5D%0A%20%20GATE%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20ENDT%5B%22%E6%8C%89%E7%BB%88%E6%AD%A2%E8%A7%84%E5%88%99%E7%BB%88%E6%AD%A2%EF%BC%8C%E5%86%99%E5%85%A5%E8%B4%9F%E6%B8%85%E5%8D%95%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>纪律不沦为仪式的机制在<strong>接口</strong>：预注册产出 N，审计产出可信的输入分布，评估产出毛指标，统计修正把三者合成一个可复核的判定。工具不是越多越好：DSR 回答选择后的期望缩水，PBO 回答选择规则本身的质量，SPA 与 Romano-Wolf 回答相对基准的家族显著性——三个答案可能不一致，不一致本身就是报告内容。修正各有假设：DSR 依赖 Sharpe 分布的近似与方差估计，CSCV 依赖对称切分，Romano-Wolf 依赖 bootstrap 世界的相关结构，超出假设的用法要声明。也别把修正叠到一切皆死：主修正在注册时选定一个，其余作稳健性附录。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>修正救不了信息量不足：样本太短时连 DSR 的方差都估不稳，此时按终止规则走，别把「再收两年数据」当失败。本课到此刻意留一个缺口：单信号在缩水与成本后达标，只说明它<strong>作为独立下注</strong>成立；能不能进组合，取决于与既有持仓的相关、约束与加权——那是下一单元第一课（组合整合）的问题。带着这个缺口进下一单元，比假装它已被回答要好。</p><p><span class="marginnote">常见误区：把「样本太短、检验过不了」当成需要克服的失败，于是等新数据、换口径、再试一轮。实际上按终止规则停下来的研究是一份合格产出——它把「此路不通」写进负清单，替未来的自己省下整轮试错。这正是上一课止损线在统计工具层的落地。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纪律仪式化三形态：引用不输入、择优报告、误用检验对象；对策是把工具当机器用。</li><li>N 来自台账（注册加偏离），是一切缩水量的输入。</li><li>DSR、PBO、SPA/Romano-Wolf 各答一个问题，全部报告，不择优；主修正在注册时选定。</li><li>报告口径：注册与偏离、N、输入输出、缩水后判定；探索结果单列标注。</li><li>本单元收束：单信号达标留下组合缺口，由下一单元第一课接手。</li><li>出处：Harvey, Liu and Zhu (2016)；Bailey, Borwein, López de Prado and Zhu (2014, 2017)；White (2000)；Hansen (2005)；Romano and Wolf (2005)。</li></ul>',6))])}const P=B(d,[["render",h]]);export{S as __pageData,P as default};
